<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\UserAcceptedTermsOfUse;

class UserAcceptedTermsOfUseCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserAcceptedTermsOfUse $userAcceptedTermsOfUse, ?int $size): UserAcceptedTermsOfUseCursor
    {
        $next = clone $this;
        $next->sinceUid = $userAcceptedTermsOfUse->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function withLimit(int $limit): UserAcceptedTermsOfUseCursor
    {
        $next = clone $this;
        $next->limit = $limit;
        return $next;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
